# The board grew from 1100x640 to 3300x1920: the old board becomes its middle third,
# so the notes keep their layout and are not crowded in the top left corner.
OLD_IN_NEW_X, OLD_IN_NEW_Y = 1100, 640


def centre_cards(apps, schema_editor):
    apps.get_model("CampaignManager", "BoardCard").objects.update(x=F("x") + OLD_IN_NEW_X, y=F("y") + OLD_IN_NEW_Y)


def uncentre_cards(apps, schema_editor):
    BoardCard = apps.get_model("CampaignManager", "BoardCard")
    for card in BoardCard.objects.all():
        card.x = min(900, max(0, card.x - OLD_IN_NEW_X))
        card.y = min(520, max(0, card.y - OLD_IN_NEW_Y))
        card.save(update_fields=["x", "y"])


